    var cv = Math.cos(glat * Math.PI / 180); if (Math.abs(cv) < 1e-6) cv = 1e-6;
    var dLon = LOC_GRID_DELTA / (111.32 * Math.abs(cv)), ix = Math.round(lon / dLon);
