      var mLat = (La + Lb) / 2, mLon = (Oa + Ob) / 2, mWk;
      if (dMin && dMax) { var mid = new Date((Date.parse(dMin) + Date.parse(dMax)) / 2); mWk = isNaN(mid.getTime()) ? weekOfToday() : weekOfDate(mid); }
