      var o = extra.slice();
      o.push({ v: "name", l: t("kml.fName") });
      o.push({ v: "desc", l: t("kml.fDesc") });
      if (p.folders.length) o.push({ v: "folder", l: t("kml.fFolder") });
      p.fields.forEach(function (f) { o.push({ v: "data:" + f, l: f }); });
